import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.DgAozdHm.js";const k=JSON.parse('{"title":"升级","description":"","frontmatter":{},"headers":[],"relativePath":"guide/upgrade.md","filePath":"guide/upgrade.md","lastUpdated":1792817471000}'),n={name:"guide/upgrade.md"};function l(o,a,p,h,d,r){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h1><h2 id="面板内升级" tabindex="-1">面板内升级 <a class="header-anchor" href="#面板内升级" aria-label="Permalink to &quot;面板内升级&quot;">​</a></h2><p><strong>设置</strong> → <strong>系统与升级</strong> → <strong>面板自升级</strong> → <strong>检查更新</strong> → <strong>立即升级</strong>。</p><p>升级会拉取新镜像并重建前后端容器，约 1 分钟后刷新页面即可。页面没有变化时，通常是浏览器或 CDN 缓存，刷新或清理缓存即可。</p><h2 id="脚本升级" tabindex="-1">脚本升级 <a class="header-anchor" href="#脚本升级" aria-label="Permalink to &quot;脚本升级&quot;">​</a></h2><p>在面板部署目录（存放 <code>docker-compose.yml</code> 和 <code>.env</code> 的目录）重新运行安装脚本，选 <code>2. 更新面板</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/jacob-bytes/hoplane/releases/latest/download/panel_install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./panel_install.sh</span></span></code></pre></div><p>数据会保留，更新前会自动备份到部署目录的 <code>backups/</code>。</p><h2 id="指定版本" tabindex="-1">指定版本 <a class="header-anchor" href="#指定版本" aria-label="Permalink to &quot;指定版本&quot;">​</a></h2><p>到 <a href="https://github.com/jacob-bytes/hoplane/releases" target="_blank" rel="noreferrer">Releases</a> 复制对应版本的命令，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/jacob-bytes/hoplane/releases/download/3.0.7/panel_install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./panel_install.sh</span></span></code></pre></div><h2 id="agent-升级" tabindex="-1">agent 升级 <a class="header-anchor" href="#agent-升级" aria-label="Permalink to &quot;agent 升级&quot;">​</a></h2><p><strong>服务器</strong> 页选择服务器 → <strong>升级</strong>，留空版本即使用最新版；点 <strong>多选</strong> 可以批量升级。也可以在服务器上重新运行服务器安装脚本。</p><p>面板升级后建议把 agent 也升级到同一版本：新功能（例如回程检测、订阅流量统计）需要新 agent，旧 agent 能照常转发，只是用不了这些功能。内核（Xray / sing-box / Snell）的版本在 <strong>落地 → 内核</strong> 里单独更换，见 <a href="./kernels">内核与协议</a>。</p><h2 id="从-0-1-0-升级到-0-2-0" tabindex="-1">从 0.1.0 升级到 0.2.0 <a class="header-anchor" href="#从-0-1-0-升级到-0-2-0" aria-label="Permalink to &quot;从 0.1.0 升级到 0.2.0&quot;">​</a></h2><p>0.2.0 把内部标识符统一成了 Hoplane 前缀：环境变量、容器名、agent 的安装目录和服务名、nftables 表名、发布资产都变了。</p><p><strong>面板</strong></p><p>在部署目录重新运行安装脚本（选 <code>2. 更新面板</code>）即可。脚本启动前会移除旧的 <code>flux-panel-backend</code> / <code>flux-panel-postgres</code> / <code>vite-frontend</code> 容器；数据卷用的是固定名字（<code>sqlite_data</code>、<code>postgres_data</code>），数据不受影响，订阅链接也不变。</p><p><strong>agent</strong></p><p>需要重装，别指望面板里点「升级」就地换掉：旧 agent 装在 <code>/etc/flux_agent</code>、服务叫 <code>flux_agent</code>，和新版本对不上。在 <strong>服务器</strong> 页对每台机器重新生成安装命令，到服务器上执行一遍：</p><ul><li>新脚本会先停用并删除旧的 <code>flux_agent</code> 服务与 <code>/etc/flux_agent</code></li><li>旧 agent 是 Docker 容器方式时，新命令会先 <code>docker rm -f flux_agent</code></li><li>旧 nftables 表（<code>inet flvx</code>、<code>inet flvx_kernel</code>）会在 agent 下次同步规则时被删掉，不会重复计数或继续拦端口</li></ul><p>升级完检查一下 <strong>节点</strong> 页的流量统计和入站白名单是否正常——这两处依赖 nft 计数与旧表清理。</p><h2 id="修复面板内升级" tabindex="-1">修复面板内升级 <a class="header-anchor" href="#修复面板内升级" aria-label="Permalink to &quot;修复面板内升级&quot;">​</a></h2><p>面板内升级提示“部署docker-compose.yml不可用”时：3.0.6 及更早版本的面板内升级会把后端容器的部署目录挂载弄丢，之后面板内升级会一直提示这个错误。数据不受影响，修复一次即可：</p><ol><li><p>在服务器上进入存放 <code>docker-compose.yml</code> 和 <code>.env</code> 的目录（常见为 <code>/root</code>，或当初运行安装脚本的目录），用 <code>ls</code> 确认这两个文件都在</p></li><li><p>执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span></code></pre></div></li></ol><p>也可以在该目录运行 3.0.7 及以后的安装脚本，选“更新面板”，会顺带修复。</p>',26)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
